          {{ form.errors.translated_fields.email | capitalize }} {{ form.errors.messages.email }}
        </div>
      {%- endif -%}

      <p class="jjw-newsletter__microcopy">
        You can unsubscribe at any time.
      </p>
    </div>
  </div>
</section>

